def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    blue_bike_patches = image_patch.find("bike in the front")
    if not blue_bike_patches:
        return image_patch

    blue_bike = blue_bike_patches[0]

    bikes = image_patch.find("bike on the right diagonal from the blue bike")
    if not bikes:
        return image_patch

    bikes_on_right_diagonal = []
    for bike in bikes:
        if abs(bike.horizontal_center - blue_bike.horizontal_center) < abs(bike.vertical_center - blue_bike.vertical_center):
            bikes_on_right_diagonal.append(bike)

    if not bikes_on_right_diagonal:
        return image_patch

    black_and_silver_bikes = [bike for bike in bikes_on_right_diagonal if bike.verify_property("bike", "black and silver")]

    if black_and_silver_bikes:
        return black_and_silver_bikes[0]

    return bikes_on_right_diagonal[0]

